package br.com.admeclesial.application.projeto;
import org.springframework.beans.factory.annotation.Autowired;
import br.com.admeclesial.application.usuario.SegurancaOrganizacaoService;
import br.com.admeclesial.domain.financeiro.*; import br.com.admeclesial.infrastructure.persistence.financeiro.*; import br.com.admeclesial.infrastructure.persistence.pessoa.PessoaRepository; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class DestinacaoContribuicaoApplicationService { @Autowired SegurancaOrganizacaoService seguranca; final DestinacaoContribuicaoRepository repo; final ContribuicaoRepository contribuicoes; final CentroCustoRepository centros; public DestinacaoContribuicaoApplicationService(DestinacaoContribuicaoRepository r,ContribuicaoRepository c,CentroCustoRepository cc){repo=r;contribuicoes=c;centros=cc;}
 @Transactional public DestinacaoContribuicao criar(DestinacaoContribuicaoRequest r){var c=contribuicoes.findByUuid(r.contribuicaoUuid()).orElseThrow(()->new IllegalArgumentException("Contribuição não encontrada."));if(seguranca!=null)seguranca.validarAcessoId(c.getOrganizacaoEclesialId());if(r.valor().compareTo(c.getValor())>0)throw new IllegalArgumentException("A destinação não pode superar o valor da contribuição.");var total=repo.sumValorPorContribuicao(c.getId());if(total.add(r.valor()).compareTo(c.getValor())>0)throw new IllegalArgumentException("A soma das destinações não pode superar a contribuição.");if(r.tipo()==TipoDestinacaoContribuicao.LIVRE&&r.usoExclusivo())throw new IllegalArgumentException("Destinação livre não pode ser exclusiva.");var e=new DestinacaoContribuicao();e.setContribuicaoId(c.getId());e.setTipo(r.tipo());e.setDescricao(r.descricao());e.setValor(r.valor());e.setUsoExclusivo(r.usoExclusivo());if(r.centroCustoUuid()!=null){var cc=centros.findByUuid(r.centroCustoUuid()).orElseThrow(()->new IllegalArgumentException("Centro de custo não encontrado."));if(!cc.getAtivo()||!cc.getOrganizacaoEclesialId().equals(c.getOrganizacaoEclesialId()))throw new IllegalArgumentException("Centro de custo incompatível com a contribuição.");e.setCentroCustoId(cc.getId());}return repo.save(e);}
 @Transactional(readOnly=true) public List<DestinacaoContribuicao> listar(){return repo.findAll().stream().filter(e->{var c=contribuicoes.findById(e.getContribuicaoId()).orElse(null);if(c==null)return false;try{if(seguranca!=null)seguranca.validarAcessoId(c.getOrganizacaoEclesialId());return true;}catch(org.springframework.security.access.AccessDeniedException ex){return false;}}).toList();}
}
